using System; using System.Buffers.Binary;
namespace SoulboundLegends.NetworkTransport;
public readonly struct PacketHeader{public const ushort Magic=0x534C; public const byte Version=1; public const int Size=39; public readonly PacketFlags Flags; public readonly TransportChannel Channel; public readonly NetworkMessageType Type; public readonly ulong ConnectionId; public readonly uint Sequence,Ack,AckBits; public readonly ushort PayloadLength; public readonly ulong Nonce;
 public PacketHeader(PacketFlags f,TransportChannel c,NetworkMessageType t,ulong id,uint s,uint a,uint bits,ushort len,ulong nonce){Flags=f;Channel=c;Type=t;ConnectionId=id;Sequence=s;Ack=a;AckBits=bits;PayloadLength=len;Nonce=nonce;}
 public void Write(Span<byte> b){BinaryPrimitives.WriteUInt16LittleEndian(b,Magic);b[2]=Version;b[3]=(byte)Flags;b[4]=(byte)Channel;BinaryPrimitives.WriteUInt16LittleEndian(b[5],(ushort)Type);BinaryPrimitives.WriteUInt64LittleEndian(b[7],ConnectionId);BinaryPrimitives.WriteUInt32LittleEndian(b[15],Sequence);BinaryPrimitives.WriteUInt32LittleEndian(b[19],Ack);BinaryPrimitives.WriteUInt32LittleEndian(b[23],AckBits);BinaryPrimitives.WriteUInt16LittleEndian(b[27],PayloadLength);BinaryPrimitives.WriteUInt64LittleEndian(b[29],Nonce);}
 public static bool TryRead(ReadOnlySpan<byte>b,out PacketHeader h){h=default;if(b.Length<Size)return false;if(BinaryPrimitives.ReadUInt16LittleEndian(b)!=Magic||b[2]!=Version)return false;var len=BinaryPrimitives.ReadUInt16LittleEndian(b[27]);if(len>65535)return false;h=new PacketHeader((PacketFlags)b[3],(TransportChannel)b[4],(NetworkMessageType)BinaryPrimitives.ReadUInt16LittleEndian(b[5]),BinaryPrimitives.ReadUInt64LittleEndian(b[7]),BinaryPrimitives.ReadUInt32LittleEndian(b[15]),BinaryPrimitives.ReadUInt32LittleEndian(b[19]),BinaryPrimitives.ReadUInt32LittleEndian(b[23]),len,BinaryPrimitives.ReadUInt64LittleEndian(b[29]));return b.Length>=Size+len+(((h.Flags&PacketFlags.Authenticated)!=0)?32:0);}
}
